using FScript.Extensibility;
using FScript.Numerics.Extensions;
using System.Text;
static string Format(ScriptType t) => t is ScriptType.TFun f ? $"{Types.typeToString(f.Item1)} -> {Format(f.Item2)}" : Types.typeToString(t);
var registration = NumericsExtension.CreateRegistration();
var text = new StringBuilder("# FScript registration reference\n\nGenerated by `make reference`; verified against the actual SDK registration by `make verify-reference`. See [operation semantics](operations.md) for argument names, policies, and examples. All schemes are monomorphic and curried; `NDArray` has a runtime dtype.\n");
foreach (var group in registration.Functions.OrderBy(f => f.Name, StringComparer.Ordinal).GroupBy(f => f.Name.Split('.')[0]))
{
    text.Append($"\n## {group.Key}\n\n| Function | Signature |\n| --- | --- |\n");
    foreach (var f in group)
        text.Append($"| `{f.Name}` | `{Format(f.Scheme.Item2)}` |\n");
}
text.Append("\n## Type descriptors\n\nAll descriptors have `HostManaged = true`. Script construction and both update forms are forbidden. Fields are immutable snapshots; hidden state is never projected. `Id` is stable per CLR object, so ordinary equality is identity-based.\n");
foreach (var descriptor in registration.Types)
{
    text.Append($"\n### {descriptor.Name}\n\n| Field | Type | Purpose |\n| --- | --- | --- |\n");
    foreach (var field in descriptor.Fields)
        text.Append($"| `{field.Key}` | `{Types.typeToString(field.Value)}` | {field.Key switch { "Id" => "Stable per-instance identity.", "DType" => "Element type name.", "Shape" => "Dimension lengths.", "Strides" => "Element strides, including broadcast zeros.", "IsReadOnly" => "True for broadcast views and their derived views.", "IsContiguous" => "Row-major contiguous layout.", "IsFortranContiguous" => "Column-major contiguous layout.", "Rank" => "Number of axes.", "Size" => descriptor.Name == "NDArray" ? "Number of logical elements." : "Order of the square factorization.", "FeatureCount" => "Expected input columns.", "ClusterCount" => "Number of clusters.", "ComponentCount" => "Number of retained principal components.", "Iterations" => "Iterations performed during fitting.", "Converged" => "Whether the documented tolerance was met.", "Inertia" => "Sum of squared distances at fitted centers.", _ => throw new InvalidOperationException(field.Key) }} |\n");
}
string path = Path.GetFullPath("docs/specs/registration.md");
if (args.Contains("--check")) { if (!File.Exists(path) || File.ReadAllText(path) != text.ToString()) throw new InvalidOperationException("Registration documentation is stale; run make reference."); Console.WriteLine("Registration reference matches all functions and descriptor fields."); } else File.WriteAllText(path, text.ToString());
